/// Options for producing a normalized label.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct NormalizeOptions {
    pub prefix: &'static str,
    pub lowercase: bool,
}

impl Default for NormalizeOptions {
    fn default() -> Self {
        Self {
            prefix: "",
            lowercase: true,
        }
    }
}

/// Produces the canonical storage form for a label.
pub fn normalize_label(input: &str) -> String {
    normalize_label_with(input, NormalizeOptions::default())
}

/// Normalizes a label with an optional prefix and case policy.
pub fn normalize_label_with(input: &str, options: NormalizeOptions) -> String {
    let trimmed = input.trim();
    let value = if options.lowercase {
        trimmed.to_ascii_lowercase()
    } else {
        trimmed.to_owned()
    };
    format!("{}{}", options.prefix, value)
}

use label_normalizer::{NormalizeOptions, normalize_label, normalize_label_with};

#[test]
fn normalizes_whitespace_and_case() {
    assert_eq!(normalize_label("  Ready FOR Review "), "ready for review");
}

#[test]
fn supports_prefixes_and_preserved_case() {
    let options = NormalizeOptions {
        prefix: "status/",
        lowercase: false,
    };
    assert_eq!(normalize_label_with(" Ready " , options), "status/Ready");
}
